#r "nuget: MSBuild.StructuredLogger, 2.2.405"

using Microsoft.Build.Logging.StructuredLogger;
using System.Linq;

var binlogPath = "/tmp/sv-3d575ea4257e46ab984d367c6fa00039/build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// List all projects and their results
var projects = build.FindChildrenRecursive<Project>().ToList();
Console.WriteLine($"=== PROJECTS ({projects.Count}) ===");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
}

// Check package references in Services.csproj
Console.WriteLine("\n=== Looking for PackageReference items in Services.csproj ===");
var servicesProject = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (servicesProject != null)
{
    var items = servicesProject.FindChildrenRecursive<AddItem>()
        .Where(i => i.Name == "PackageReference").ToList();
    foreach (var item in items)
    {
        Console.WriteLine($"  PackageReference: {item.Text}");
    }

    // Also look for project references
    var projRefs = servicesProject.FindChildrenRecursive<AddItem>()
        .Where(i => i.Name == "ProjectReference").ToList();
    foreach (var pr in projRefs)
    {
        Console.WriteLine($"  ProjectReference: {pr.Text}");
    }
}

// Check if any other projects reference Services.csproj
Console.WriteLine("\n=== Projects referencing Services.csproj ===");
foreach (var p in projects.Where(p => p.Name != "Services.csproj"))
{
    var refs = p.FindChildrenRecursive<AddItem>()
        .Where(i => i.Name == "ProjectReference" && i.Text.Contains("Services")).ToList();
    foreach (var r in refs)
    {
        Console.WriteLine($"  {p.Name} -> {r.Text}");
    }
}
EOF
